/* ─────────────────────────────────────────────────────────────────────
   CRO redesign May 2026 — PDP "Build Your Matching Set" flow
   ─────────────────────────────────────────────────────────────────────

   Scope: anything inside .product__info-container--matching-set, i.e.
   only products tagged / collected as matching-set / mommy-and-me /
   daddy-and-me / family-matching. Non-matching-set products keep their
   Dawn-default presentation.

   Goals (from CRO spec):
   ─ Single primary CTA      (hide the standalone Add-to-Cart submit)
   ─ Family-member cards     (pills + qty stepper + remove)
   ─ Progressive disclosure  (+ Add Dad / + Add Baby chips)
   ─ Live summary            (count, total, savings) above the CTA
   ─ Compact trust row       (under the CTA, not below the fold)
   ─ Collapse measurement /
     Purchase Confidence     (so first viewport is cards + CTA)
   ─ Compress vertical
     spacing ~40–60%
   ────────────────────────────────────────────────────────────────── */

/* Make sure the matching-set block paints — historically it ships
   hidden until JS unhides; on matching-set products we want it
   prominently visible. */
.product__info-container--matching-set .product-desktop-ux {
  display: block;
}

.product__info-container--matching-set .product-matching-set__role-price,
.product__info-container--matching-set .product-matching-set__card-price,
.product__info-container--matching-set .product-matching-set__card-price--header {
  display: none !important;
}

/* 1. Single primary CTA + single source of size truth.
   On matching-set products the standalone Add-to-Cart submit + its
   dynamic checkout button are hidden so the matching-set CTA below
   reads as the only primary path. Customers buying a single piece
   simply leave one card visible. The main variant-selects is also
   hidden — sizing happens per-family-member-card, not via the
   standalone size picker, so showing both creates two competing
   size selectors. Hiding only the picker UI; the underlying
   variant-selects element still receives change events from the
   bundle so anything downstream of it (e.g. price/url sync) keeps
   working. */
.product__info-container--matching-set .product-form__submit,
.product__info-container--matching-set .product-form__buttons {
  display: none !important;
}
.product__info-container--matching-set .product-form__dynamic-checkout {
  display: none !important;
}
/* On bundle products hide the legacy variant pickers that are now
   handled per-family-member-card inside the bundle:
   • SIZE — discriminator: aria-describedby="size-conversion-message"
     emitted only on size fieldset / size <select> by the Liquid template.
   • COLOR — discriminator: .product-form__input--swatch or
     .product-form__input--color-image (color picker variants in Dawn).
   Per-card axis pickers cover both. Type (Shirt/Dress) stays visible
   above the bundle because it's a role-discriminator that re-seeds
   the default-visible family members (handled by JS reactivity). */
.product__info-container--matching-set variant-selects > fieldset[aria-describedby="size-conversion-message"],
.product__info-container--matching-set variant-selects > .product-form__input:has([aria-describedby="size-conversion-message"]),
.product__info-container--matching-set variant-selects > fieldset.product-form__input--swatch,
.product__info-container--matching-set variant-selects > fieldset.product-form__input--color-image,
.product__info-container--matching-set variant-selects > .product-form__input--swatch,
.product__info-container--matching-set variant-selects > .product-form__input--color-image {
  display: none !important;
}

/* When Type perfectly partitions roles (data-type-implicit attribute
   set by initMatchingSetBuilder via detectImplicitTypeMapping), the
   global Type picker is redundant — each role's natural Type is
   implied. Hide every remaining option group; the JS will still keep
   it in the DOM so any underlying form data stays consistent. The
   ::variant-selects element itself still emits change events which
   the bundle ignores in implicit mode. */
.product__info-container--matching-set[data-type-implicit="true"] variant-selects > .product-form__input,
.product__info-container--matching-set[data-type-implicit="true"] variant-selects > fieldset.product-form__input,
.product__info-container--matching-set[data-type-implicit="true"] variant-selects > .product-form__step-heading {
  display: none !important;
}
/* Hide the step-mini-headings too (they were "1. CHOOSE SIZE / 2. PICK
   COLOR" numbering that no longer makes sense once size is removed). */
.product__info-container--matching-set variant-selects > .product-form__step-heading {
  display: none !important;
}
/* Hide the legacy size-guide subtree (snapshot, conversion message,
   chart wrapper). The matching-size-guide details element stays in
   the DOM with [hidden] so the per-card "Find {role}'s fit" link can
   still un-hide it via the shared trigger handler. */
.product__info-container--matching-set variant-selects > #size-conversion-message,
.product__info-container--matching-set variant-selects > .matching-size-guide__snapshot,
.product__info-container--matching-set variant-selects > .size-chart-wrapper {
  display: none !important;
}

/* Style the surviving Color / Type / Style pickers above the bundle
   card so they read as the global "shared across family" pickers and
   don't feel like leftover Dawn chrome. */
.product__info-container--matching-set variant-selects > .product-form__input {
  margin: 0.4rem 0 0.9rem !important;
}
.product__info-container--matching-set variant-selects > .product-form__input legend.form__label,
.product__info-container--matching-set variant-selects > .product-form__input > label.form__label {
  font-size: 1.15rem;
  font-weight: 700;
  color: #101418;
  margin-bottom: 0.45rem;
}

/* HUGE WHITE GAP root cause: sections/main-product.liquid reserves
   24.3rem (~243px) min-height on .matching-size-guide__snapshot--reserved
   to prevent layout shift when the size-guide snapshot loads. On
   bundle products that snapshot is hidden, so the reserved space
   becomes visible empty space. Override the reservation. */
.product__info-container--matching-set .matching-size-guide__snapshot,
.product__info-container--matching-set .matching-size-guide__snapshot--reserved,
.product__info-container--matching-set .matching-size-guide__snapshot--reserved:empty {
  display: none !important;
  min-height: 0 !important;
  visibility: hidden !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}
.product__info-container--matching-set variant-selects > details.matching-size-guide[hidden] {
  display: none !important;
}
.product__info-container--matching-set .product-form__quantity {
  display: none !important;
}

/* The legacy buy-buttons.liquid renders a 4-pill trust strip (Secure
   Checkout / 30-day return window / Free standard shipping / Family
   matching made easy) plus a "Need help?" line above the bundle card.
   That information is duplicated by the Purchase Confidence module
   below the CTA. Hide it on bundle products so the bundle leads. */
.product__info-container--matching-set .product__trust-strip,
.product__info-container--matching-set .product__trust-note {
  display: none !important;
}

/* Aggressively zero margins/padding on every Dawn block container that
   sits between the price block and the bundle on bundle products. This
   eliminates the residual whitespace the previous pass missed (the
   product-form, the volume-pricing note, low-stock-urgency div, the
   pickup availability shell, the size-conversion message, etc.). */
.product__info-container--matching-set .product-form {
  margin: 0 !important;
  padding: 0 !important;
}
.product__info-container--matching-set .product-form__error-message-wrapper,
.product__info-container--matching-set .product-form__error-message-wrapper:empty,
.product__info-container--matching-set .pickup-availability,
.product__info-container--matching-set .pickup-availability-preview,
.product__info-container--matching-set .pickup-availability-info,
.product__info-container--matching-set .volume-pricing-note,
.product__info-container--matching-set .low-stock-urgency:empty {
  display: none !important;
}
.product__info-container--matching-set product-form,
.product__info-container--matching-set product-form .product-form,
.product__info-container--matching-set .product-form__buttons {
  margin: 0 !important;
  padding: 0 !important;
  min-height: 0 !important;
}
/* If the buy_buttons block leaves an empty <product-form> shell behind
   (after we hide its visible children), collapse that shell entirely. */
.product__info-container--matching-set product-form:empty {
  display: none !important;
}
/* The variant_picker block emits a wrapper that might still claim
   vertical space even when its children are display:none — collapse
   the &lt;variant-selects&gt; element itself if all visible children are
   hidden. (The matching-size-guide details retains [hidden] from JS
   so it doesn't reserve space.) */
.product__info-container--matching-set variant-selects {
  display: block;
  margin: 0 !important;
  padding: 0 !important;
}

/* 2. Compress the picker → CTA distance.
   Dawn ships generous vertical rhythm; on bundle products we want the
   CTA inside the first mobile viewport. Trims ~40–60% off the gaps,
   and zeros-out the gap between the price block and the bundle card
   that opens up when we hide the variant picker + trust strip. */
.product__info-container--matching-set .product-form,
.product__info-container--matching-set .product-form__input {
  margin-top: 0.6rem;
  margin-bottom: 0.6rem;
}
.product__info-container--matching-set .matching-size-guide,
.product__info-container--matching-set .matching-size-guide__snapshot {
  margin-top: 0.6rem;
}
/* Collapse the variant_picker block when its children are all hidden
   on bundle products. The block container itself still paints unless
   we zero its margins. */
.product__info-container--matching-set .product-form {
  margin: 0;
}
.product__info-container--matching-set variant-selects:empty,
.product__info-container--matching-set variant-selects {
  margin: 0;
  padding: 0;
}
/* The buy-buttons block sits between price and bundle — its empty
   wrapper margins create the visible gap. */
.product__info-container--matching-set product-form {
  margin: 0;
}

/* 3. Purchase Confidence module — UPDATED May 11 2026.
   Initial pass hid .additional-info on bundle products in favor of a
   small 3-checkmark strip inside the bundle card. Frank flagged this
   removed useful info (shipping country, delivery date, returns,
   secure-checkout details, size-guide link). Restore the full module
   directly below the bundle CTA — DOM order in main-product.liquid
   already places .additional-info immediately after the bundle card,
   so a small spacing tweak gets it visually adjacent to the CTA. */
.product__info-container--matching-set ~ .additional-info,
[data-has-matching-set="true"] ~ .additional-info,
.product__info-wrapper:has(.product__info-container--matching-set) .additional-info {
  margin-top: 0.6rem;
}

/* On bundle products specifically, two parts of Purchase Confidence
   are redundant and we hide them:
   • .dlm-pc-compact-row (Secure checkout / Free shipping / 30-day
     returns / Ships to {country}) — duplicated by the three big
     promise rows directly below it inside the same card.
   • .dlm-pc-details (Size guide & fit → link) — now redundant
     because the per-pill pinned tooltip auto-shows measurements
     when a size is selected.
   Non-bundle products keep both elements untouched. */
.product__info-wrapper:has(.product__info-container--matching-set) .dlm-pc-compact-row,
.product__info-wrapper:has(.product__info-container--matching-set) .dlm-pc-details {
  display: none !important;
}

/* 4. The bundle card itself — softer container, no marketplace borders. */
.product__info-container--matching-set .product-matching-set {
  margin: 1rem 0 1.2rem;
  padding: 1.4rem 1.4rem 1.2rem;
  border-radius: 1.8rem;
  border: 0.1rem solid rgba(29, 134, 86, 0.18);
  background: linear-gradient(180deg, #fbfdfa 0%, #f4f9f1 100%);
  box-shadow: 0 0.6rem 2rem rgba(29, 134, 86, 0.08);
}
.product__info-container--matching-set .product-matching-set__header {
  margin-bottom: 1rem;
  text-align: left;
}
.product__info-container--matching-set .product-matching-set__eyebrow {
  margin: 0 0 0.35rem;
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #1D8656;
}
.product__info-container--matching-set .product-matching-set__title {
  margin: 0 0 0.4rem;
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.25;
  color: #101418;
}
.product__info-container--matching-set .product-matching-set__copy {
  margin: 0;
  font-size: 1.2rem;
  line-height: 1.45;
  color: rgba(17, 24, 39, 0.7);
}
.product__info-container--matching-set .product-matching-set__guide {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.45rem;
  margin: 0.9rem 0 0;
  padding: 0;
  list-style: none;
}
.product__info-container--matching-set .product-matching-set__guide li {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  min-width: 0;
  color: rgba(17, 24, 39, 0.72);
  font-size: 1.08rem;
  line-height: 1.35;
}
.product__info-container--matching-set .product-matching-set__guide li::before {
  content: '';
  flex: 0 0 auto;
  width: 0.62rem;
  height: 0.62rem;
  margin-top: 0.42rem;
  border-radius: 999px;
  background: #1D8656;
  box-shadow: 0 0 0 0.24rem rgba(29, 134, 86, 0.1);
}

.product__info-container--matching-set .product-matching-set__step-heading {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin: 0 0 0.8rem;
  color: #101418;
}

.product__info-container--matching-set .product-matching-set__step-heading span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 2.4rem;
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 999px;
  background: #1D8656;
  color: #ffffff;
  font-size: 1.15rem;
  font-weight: 800;
}

.product__info-container--matching-set .product-matching-set__step-heading strong {
  font-size: 1.22rem;
  line-height: 1.25;
}

.product__info-container--matching-set .product-matching-set__role-step {
  margin-top: 1rem;
  padding: 1rem;
  border-radius: 1.4rem;
  background: #ffffff;
  border: 0.1rem solid rgba(17, 24, 39, 0.08);
}

.product__info-container--matching-set .product-matching-set__role-buttons {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.7rem;
}

.product__info-container--matching-set .product-matching-set__role-button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  min-height: 5.4rem;
  padding: 0.9rem 1rem;
  border: 0.14rem solid rgba(17, 24, 39, 0.14);
  border-radius: 1.2rem;
  background: #ffffff;
  color: #101418;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.14s ease, background 0.14s ease, box-shadow 0.14s ease;
}

.product__info-container--matching-set .product-matching-set__role-button:hover,
.product__info-container--matching-set .product-matching-set__role-button:focus-visible {
  border-color: rgba(29, 134, 86, 0.55);
  background: #f6fbf7;
}

.product__info-container--matching-set .product-matching-set__role-button.is-selected {
  border-color: #1D8656;
  background: #f0faf4;
  box-shadow: inset 0 0 0 0.1rem rgba(29, 134, 86, 0.18);
}

.product__info-container--matching-set .product-matching-set__role-label {
  min-width: 0;
  font-size: 1.22rem;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.product__info-container--matching-set .product-matching-set__role-hint {
  margin: 0.75rem 0 0;
  font-size: 1.08rem;
  line-height: 1.4;
  color: rgba(17, 24, 39, 0.64);
}

/* 5. Stacked cards (mobile-first, single column). */
.product__info-container--matching-set .product-matching-set__grid {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
}
.product__info-container--matching-set .product-matching-set__card {
  padding: 1.2rem 1.2rem 1rem;
  border-radius: 1.4rem;
  background: #ffffff;
  border: 0.1rem solid rgba(17, 24, 39, 0.08);
  box-shadow: 0 0.3rem 1rem rgba(17, 24, 39, 0.04);
}
.product__info-container--matching-set .product-matching-set__card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  margin-bottom: 0.55rem;
}
.product__info-container--matching-set .product-matching-set__card .product-matching-set__step-heading {
  margin-bottom: 1rem;
}
.product__info-container--matching-set .product-matching-set__card-title {
  font-size: 1.35rem;
  font-weight: 700;
  color: #101418;
  letter-spacing: 0.005em;
}
.product__info-container--matching-set .product-matching-set__card-remove {
  width: 2.8rem;
  height: 2.8rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: rgba(17, 24, 39, 0.45);
  font-size: 2rem;
  line-height: 1;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}
.product__info-container--matching-set .product-matching-set__card-remove:hover {
  background: rgba(17, 24, 39, 0.06);
  color: #1a1a1a;
}
.product__info-container--matching-set .product-matching-set__card-helper {
  display: block;
  margin: 0 0 0.6rem;
  font-size: 1.05rem;
  color: rgba(17, 24, 39, 0.6);
}

/* 6. Size pills. */
.product__info-container--matching-set .product-matching-set__size-row {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  margin: 0.2rem 0 0.65rem;
}

.product__info-container--matching-set .product-matching-set__pills {
  display: flex;
  flex-wrap: wrap;
  flex: 1 1 auto;
  gap: 0.55rem;
  min-width: 0;
  margin: 0;
}

.product__info-container--matching-set .product-matching-set__fit-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 4.4rem;
  width: 4.4rem;
  height: 4.4rem;
  padding: 0;
  border: 0.15rem solid rgba(17, 24, 39, 0.16);
  border-radius: 999px;
  background: #ffffff;
  color: #146642;
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease, color 0.12s ease, transform 0.05s ease;
}

.product__info-container--matching-set .product-matching-set__fit-icon svg {
  width: 2rem;
  height: 2rem;
}

.product__info-container--matching-set .product-matching-set__fit-icon:hover,
.product__info-container--matching-set .product-matching-set__fit-icon:focus-visible,
.product__info-container--matching-set .product-matching-set__fit-icon[aria-expanded='true'] {
  border-color: #1D8656;
  background: rgba(29, 134, 86, 0.08);
  color: #0f5235;
}

.product__info-container--matching-set .product-matching-set__fit-icon:focus-visible {
  outline: 0.22rem solid rgba(29, 134, 86, 0.35);
  outline-offset: 0.2rem;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel[hidden] {
  display: none !important;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel {
  margin: -0.15rem 0 0.75rem;
  padding: 0.55rem;
  border: 0.1rem solid rgba(17, 24, 39, 0.12);
  border-radius: 0.8rem;
  background: #fbfbfd;
  overflow: visible;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.55rem;
  margin-bottom: 0.45rem;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel-bar strong {
  min-width: 0;
  color: #101418;
  font-size: 1.05rem;
  font-weight: 800;
  line-height: 1.2;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__card {
  border: 0;
  border-radius: 0;
  background: transparent;
  overflow: visible;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table-wrap {
  overflow: visible;
  position: relative;
  isolation: isolate;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table {
  table-layout: fixed;
  font-size: 0.9rem;
  line-height: 1.15;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table th,
.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table td {
  padding: 0.32rem 0.34rem;
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: normal;
  vertical-align: middle;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table th:first-child,
.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table td:first-child {
  position: static;
  box-shadow: none;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table tbody tr:hover td,
.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table tbody tr:focus-within td,
.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table tbody tr:focus td {
  background: rgba(29, 134, 86, 0.12);
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table tbody tr:hover td:first-child,
.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table tbody tr:focus-within td:first-child,
.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table tbody tr:focus td:first-child {
  background: rgba(29, 134, 86, 0.18);
  color: #0f5235;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table tbody tr.is-selected td {
  background: rgba(226, 197, 168, 0.18);
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table tbody tr.is-selected td:first-child {
  background: #eadbce;
  color: #8a5c3e;
  font-weight: 800;
}

.product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table tbody tr:focus-visible {
  outline: 0.2rem solid rgba(29, 134, 86, 0.42);
  outline-offset: -0.2rem;
}

@media screen and (max-width: 749px) {
  .product__info-container--matching-set .product-matching-set__inline-fit-panel {
    padding: 0.5rem;
  }

  .product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table-wrap {
    overflow-x: auto;
    overflow-y: visible;
    overscroll-behavior-x: none;
    -webkit-overflow-scrolling: touch;
  }

  .product__info-container--matching-set .product-matching-set__inline-fit-panel .dlm-fit-frozen-column {
    position: absolute;
    top: 0;
    left: 0;
    z-index: 20;
    width: var(--dlm-fit-frozen-width, 4.8rem);
    height: var(--dlm-fit-frozen-height, 100%);
    min-height: 100%;
    transform: translate3d(var(--dlm-fit-overlay-scroll-left, 0px), 0, 0);
    pointer-events: none;
    background: #ffffff;
    box-shadow: 0.18rem 0 0 #ffffff, 0.34rem 0 0 rgba(17, 24, 39, 0.1);
  }

  .product__info-container--matching-set .product-matching-set__inline-fit-panel .dlm-fit-frozen-column__cell {
    position: absolute;
    left: 0;
    display: flex;
    align-items: center;
    width: 100%;
    box-sizing: border-box;
    padding: 0.42rem 0.42rem;
    border-bottom: 0.1rem solid rgba(17, 24, 39, 0.08);
    background: #ffffff;
    color: #111827;
    font-size: 0.98rem;
    font-weight: 700;
    line-height: 1.15;
    white-space: normal;
    overflow-wrap: normal;
    word-break: normal;
    overflow: hidden;
  }

  .product__info-container--matching-set .product-matching-set__inline-fit-panel .dlm-fit-frozen-column__cell--head {
    background: #f7efe8;
    color: #374151;
    font-weight: 800;
  }

  .product__info-container--matching-set .product-matching-set__inline-fit-panel .dlm-fit-frozen-column__cell--selected {
    background: #eadbce;
    color: #8a5c3e;
    font-weight: 800;
    box-shadow: 0.18rem 0 0 #eadbce, 0.34rem 0 0 rgba(17, 24, 39, 0.1);
  }

  .product__info-container--matching-set .product-matching-set__inline-fit-panel .dlm-fit-frozen-column__cell--active:not(.dlm-fit-frozen-column__cell--selected) {
    background: #dff3e9;
    color: #0f5235;
    font-weight: 800;
    box-shadow: 0.18rem 0 0 #dff3e9, 0.34rem 0 0 rgba(17, 24, 39, 0.1);
  }

  .product__info-container--matching-set .product-matching-set__inline-fit-panel .matching-size-guide__table {
    min-width: max(100%, var(--dlm-fit-table-min-width, 100%));
    border-collapse: separate;
    border-spacing: 0;
    table-layout: auto;
