/* Pill tooltip — Shein-style measurement popover.
   Source of truth: the product's <table id="size-chart"> parsed by
   parseSizeGuideTable() in product-desktop-ux.js. Same data that
   powers the legacy "Compare family sizes" disclosure, so the figures
   stay in sync with whatever Frank maintains per product.

   Shows on desktop hover or keyboard focus, and on mobile tap
   (focus survives a tap on iOS/Android). Tap outside the pill closes
   it because the browser moves focus away. */
.product__info-container--matching-set .product-matching-set__pill-wrap {
  position: relative;
  display: inline-flex;
}
.product__info-container--matching-set .product-matching-set__pill-tooltip {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 0.55rem);
  z-index: 30;
  min-width: 18rem;
  max-width: 24rem;
  padding: 0.85rem 1rem;
  border-radius: 0.9rem;
  background: #1a1a1a;
  color: #ffffff;
  font-size: 1.1rem;
  line-height: 1.4;
  text-align: left;
  box-shadow: 0 0.8rem 2rem rgba(17, 24, 39, 0.28);
  transform: translate(-50%, 0.3rem);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.12s ease, transform 0.12s ease;
}
.product__info-container--matching-set .product-matching-set__pill-tooltip::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 0.6rem solid transparent;
  border-top-color: #1a1a1a;
}
.product__info-container--matching-set .product-matching-set__pill-wrap:hover .product-matching-set__pill-tooltip,
.product__info-container--matching-set .product-matching-set__pill-wrap:focus-within .product-matching-set__pill-tooltip {
