  }

  .product__info-container--matching-set .product-matching-set__mobile-size-panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    margin-bottom: 0.55rem;
  }

  .product__info-container--matching-set .product-matching-set__mobile-size-panel-title {
    min-width: 0;
    color: #101418;
    font-size: 1.18rem;
    line-height: 1.25;
  }

  .product__info-container--matching-set .product-matching-set__mobile-size-panel .product-matching-set__pill-tooltip-toggle {
    background: rgba(29, 134, 86, 0.1);
  }

  .product__info-container--matching-set .product-matching-set__mobile-size-panel .product-matching-set__pill-tooltip-unit {
    color: #146642;
  }

  .product__info-container--matching-set .product-matching-set__mobile-size-panel .product-matching-set__pill-tooltip-unit:hover,
  .product__info-container--matching-set .product-matching-set__mobile-size-panel .product-matching-set__pill-tooltip-unit:focus-visible {
    color: #0f5235;
  }

  .product__info-container--matching-set .product-matching-set__mobile-size-panel .product-matching-set__pill-tooltip-unit.is-active {
    background: #146642;
