/* ─────────────────────────────────────────────────────────────────
   Pinned compact tooltip (May 2026 rev 4)
   Replaces the large inline size panel from rev 3. When the pill is
   SELECTED and not dismissed, the same compact black tooltip from the
   hover-preview pattern stays open (.is-pinned). Adds a tiny × and a
   cm/in toggle inside its header. Picking a different size on the
   same card re-opens the pinned tooltip for the new size.
   ───────────────────────────────────────────────────────────── */

/* Pinned variant — visible without :hover / :focus-within. */
.product__info-container--matching-set .product-matching-set__pill-tooltip.is-pinned {
  opacity: 1 !important;
  pointer-events: auto !important;
  transform: translate(-50%, 0) !important;
  /* a touch wider to accommodate the toggle + close button */
  min-width: 20rem;
}

/* A pinned tooltip needs to draw above neighbouring pills (and any
   neighbour's hover tooltip that might still be lurking). */
.product__info-container--matching-set .product-matching-set__pill-wrap:has(.is-pinned) {
  z-index: 35;
}

/* The hover-state base rule keeps the floating popover visible while
   hovering a wrap; for the pinned variant we don't want hovering a
   neighbor to dim ours, so explicit re-statement above with !important. */

/* Header row inside the tooltip: title on the left, controls on the
   right when pinned. */
.product__info-container--matching-set .product-matching-set__pill-tooltip-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  margin-bottom: 0.4rem;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-controls {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  flex: 0 0 auto;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-toggle {
  display: inline-flex;
  padding: 0.15rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-unit {
  min-width: 2.4rem;
  padding: 0.18rem 0.55rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: rgba(255, 255, 255, 0.65);
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-unit:hover {
  color: #ffffff;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-unit.is-active {
  background: #ffffff;
  color: #1a1a1a;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-close {
  width: 1.9rem;
  height: 1.9rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
  font-size: 1.4rem;
  line-height: 1;
  cursor: pointer;
  transition: background 0.15s ease;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-close:hover,
.product__info-container--matching-set .product-matching-set__pill-tooltip-close:focus-visible {
  background: rgba(255, 255, 255, 0.22);
  outline: none;
}

/* On narrow viewports keep the pinned tooltip readable but not huge —
   it positions over the pill row, so the size-blurb confirmation
   beneath the pills tells the shopper what they picked even when the
   tooltip overlaps something. */
@media screen and (max-width: 480px) {
  .product__info-container--matching-set .product-matching-set__pill-tooltip.is-pinned {
    min-width: 18rem;
  }
}

/* 7. Quantity stepper + per-card price chip. */
.product__info-container--matching-set .product-matching-set__qty {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  margin-top: 0.4rem;
}
.product__info-container--matching-set .product-matching-set__qty-button {
  width: 3.4rem;
  height: 3.4rem;
  padding: 0;
  border: 0.12rem solid rgba(17, 24, 39, 0.16);
  border-radius: 999px;
  background: #ffffff;
  color: #101418;
  font-size: 1.55rem;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease;
}
.product__info-container--matching-set .product-matching-set__qty-button:hover {
  border-color: #1D8656;
  color: #1D8656;
}
.product__info-container--matching-set .product-matching-set__qty-value {
  min-width: 2.2rem;
  font-size: 1.25rem;
  font-weight: 700;
  text-align: center;
  color: #101418;
