/* "Pick a size for {role}" prompt — shown beneath the pills when a
   card has no variant selected. Soft amber so it reads as guidance,
   not error. */
.product__info-container--matching-set .product-matching-set__pick-hint {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0.5rem 0 0.4rem;
  padding: 0.55rem 0.85rem;
  border-radius: 0.9rem;
  background: #fff5e0;
  border: 0.1rem solid rgba(180, 120, 30, 0.18);
  color: #8a5a18;
  font-size: 1.1rem;
  font-weight: 600;
  line-height: 1.35;
}
.product__info-container--matching-set .product-matching-set__pick-hint svg {
  flex: 0 0 auto;
}

/* Inline contextual prompt — small, subtle, sits directly under the
   row it refers to (size pill row OR axis row). Less heavy than the
   full-width amber banner and reads as natural microcopy adjacent to
   the control it guides. Disappears as soon as the row has a value. */
.product__info-container--matching-set .product-matching-set__inline-hint {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin: 0.35rem 0 0;
  padding: 0;
  color: #b07820;
  font-size: 1rem;
  font-weight: 600;
  font-style: italic;
  line-height: 1.3;
  letter-spacing: 0.01em;
}
.product__info-container--matching-set .product-matching-set__inline-hint::before {
  content: '↑';
  display: inline-block;
  margin-right: 0.1rem;
  font-style: normal;
  font-weight: 800;
  color: #d39c4a;
}

/* Friendly confirmation line — shown beneath the pills once a size
   is picked. Replaces the dense WEIGHT/HEIGHT/CHEST grid that used
   to dominate the viewport. Full measurements still reachable via
   the per-card "Find {role}'s fit →" link below. */
.product__info-container--matching-set .product-matching-set__size-blurb {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0.5rem 0 0.4rem;
  padding: 0.55rem 0.85rem;
  border-radius: 0.9rem;
  background: rgba(29, 134, 86, 0.08);
  border: 0.1rem solid rgba(29, 134, 86, 0.18);
  color: #146642;
  font-size: 1.1rem;
  font-weight: 600;
