// create a container and set the full-size image as its background
function createOverlay(image) {
  const overlayImage = document.createElement('img');
  overlayImage.setAttribute('src', `${image.src}`);
  overlay = document.createElement('div');
  prepareOverlay(overlay, overlayImage);

  image.style.opacity = '50%';
  toggleLoadingSpinner(image);

  overlayImage.onload = () => {
    toggleLoadingSpinner(image);
    image.parentElement.insertBefore(overlay, image);
    image.style.opacity = '100%';
  };

  return overlay;
}

function prepareOverlay(container, image) {
  container.setAttribute('class', 'image-magnify-full-size');
  container.setAttribute('aria-hidden', 'true');
  container.style.backgroundImage = `url('${image.src}')`;
  container.style.backgroundColor = 'var(--gradient-background)';
}

function toggleLoadingSpinner(image) {
  const loadingSpinner = image.parentElement.parentElement.querySelector(`.loading__spinner`);
  loadingSpinner.classList.toggle('hidden');
}

function moveWithHover(image, event, zoomRatio) {
  // calculate mouse position
  const ratio = image.height / image.width;
  const container = event.target.getBoundingClientRect();
  const xPosition = event.clientX - container.left;
  const yPosition = event.clientY - container.top;
  const xPercent = `${xPosition / (image.clientWidth / 100)}%`;
  const yPercent = `${yPosition / ((image.clientWidth * ratio) / 100)}%`;

  // determine what to show in the frame
  overlay.style.backgroundPosition = `${xPercent} ${yPercent}`;
  overlay.style.backgroundSize = `${image.width * zoomRatio}px`;
}

function magnify(image, zoomRatio) {
  const overlay = createOverlay(image);
  overlay.onclick = () => overlay.remove();
  overlay.onmousemove = (event) => moveWithHover(image, event, zoomRatio);
  overlay.onmouseleave = () => overlay.remove();
}

function enableZoomOnHover(zoomRatio) {
  const images = document.querySelectorAll('.image-magnify-hover');
  images.forEach((image) => {
    image.onclick = (event) => {
      magnify(image, zoomRatio);
      moveWithHover(image, event, zoomRatio);
    };
  });
}

enableZoomOnHover(2);

if (!customElements.get('media-gallery')) {
  customElements.define(
    'media-gallery',
    class MediaGallery extends HTMLElement {
      constructor() {
        super();
        this.elements = {
          liveRegion: this.querySelector('[id^="GalleryStatus"]'),
          viewer: this.querySelector('[id^="GalleryViewer"]'),
          thumbnails: this.querySelector('[id^="GalleryThumbnails"]'),
          mobileShareButtons: Array.from(this.querySelectorAll('[data-mobile-share-button]')),
        };
        this.mql = window.matchMedia('(min-width: 750px)');
        this.mobileViewportMql = window.matchMedia('(max-width: 749px)');
        this.mobileShareClickHandler = this.handleMobileShareClick.bind(this);
        this.mobileSharePositionHandler = debounce(this.syncMobileShareButtonPosition.bind(this), 120);
        this.viewerSlideChangeHandler = debounce(this.syncMobileShareButtonPosition.bind(this), 80);
        this.mobileShareLoadHandler = this.mobileSharePositionHandler;
        this.galleryCounterPositionHandler = debounce(this.syncGalleryCounterPosition.bind(this), 120);
        this.galleryCounterSlideHandler = debounce(this.syncGalleryCounterPosition.bind(this), 80);
        this.mobileSwipeStartHandler = this.handleMobileSwipeStart.bind(this);
        this.mobileSwipeMoveHandler = this.handleMobileSwipeMove.bind(this);
        this.mobileSwipeEndHandler = this.handleMobileSwipeEnd.bind(this);
        this.mobileSwipeCancelHandler = this.handleMobileSwipeCancel.bind(this);
        this.mobileSwipeState = null;

        if (this.elements.mobileShareButtons.length) {
          this.elements.mobileShareButtons.forEach((button) => {
            button.addEventListener('click', this.mobileShareClickHandler);
          });
          if (this.elements.viewer) {
            this.syncMobileShareButtonPosition();
            window.requestAnimationFrame(() => this.syncMobileShareButtonPosition());
            window.setTimeout(() => this.syncMobileShareButtonPosition(), 220);
            this.elements.viewer.addEventListener('slideChanged', this.viewerSlideChangeHandler);
            if ('ResizeObserver' in window) {
              this.mobileShareResizeObserver = new ResizeObserver(this.mobileSharePositionHandler);
              this.mobileShareResizeObserver.observe(this.elements.viewer);
              const mediaList = this.elements.viewer.querySelector('.product__media-list');
              if (mediaList) this.mobileShareResizeObserver.observe(mediaList);
            }
          }
          window.addEventListener('load', this.mobileShareLoadHandler);
          window.addEventListener('resize', this.mobileSharePositionHandler);
          window.addEventListener('orientationchange', this.mobileSharePositionHandler);
          if (this.mobileViewportMql.addEventListener) {
            this.mobileViewportMql.addEventListener('change', this.mobileSharePositionHandler);
          } else if (this.mobileViewportMql.addListener) {
            this.mobileViewportMql.addListener(this.mobileSharePositionHandler);
          }
        }

        if (this.elements.viewer && this.querySelector('[data-gallery-stepper]')) {
          this.syncGalleryCounterPosition();
          window.requestAnimationFrame(() => this.syncGalleryCounterPosition());
          window.setTimeout(() => this.syncGalleryCounterPosition(), 220);
          this.elements.viewer.addEventListener('slideChanged', this.galleryCounterSlideHandler);
          if ('ResizeObserver' in window) {
            this.galleryCounterResizeObserver = new ResizeObserver(this.galleryCounterPositionHandler);
            this.galleryCounterResizeObserver.observe(this.elements.viewer);
            const mediaList = this.elements.viewer.querySelector('.product__media-list');
            if (mediaList) this.galleryCounterResizeObserver.observe(mediaList);
          }
          window.addEventListener('load', this.galleryCounterPositionHandler);
          window.addEventListener('resize', this.galleryCounterPositionHandler);
          window.addEventListener('orientationchange', this.galleryCounterPositionHandler);
        }

        if (this.elements.viewer && this.elements.viewer.slider) {
          this.bindMobileSwipeHandlers();
        }

        if (!this.elements.thumbnails) return;

        this.elements.viewer.addEventListener('slideChanged', debounce(this.onSlideChanged.bind(this), 500));
        this.elements.thumbnails.querySelectorAll('[data-target]').forEach((mediaToSwitch) => {
          mediaToSwitch
            .querySelector('button')
            .addEventListener('click', this.setActiveMedia.bind(this, mediaToSwitch.dataset.target));
        });
        if (this.dataset.desktopLayout.includes('thumbnail') && this.mql.matches) this.removeListSemantic();
      }

      disconnectedCallback() {
        if (this.elements.mobileShareButtons.length) {
          this.elements.mobileShareButtons.forEach((button) => {
            button.removeEventListener('click', this.mobileShareClickHandler);
          });
          if (this.elements.viewer) {
            this.elements.viewer.removeEventListener('slideChanged', this.viewerSlideChangeHandler);
          }
          if (this.mobileShareResizeObserver) {
            this.mobileShareResizeObserver.disconnect();
          }
          window.removeEventListener('load', this.mobileShareLoadHandler);
          window.removeEventListener('resize', this.mobileSharePositionHandler);
          window.removeEventListener('orientationchange', this.mobileSharePositionHandler);
          if (this.mobileViewportMql.removeEventListener) {
            this.mobileViewportMql.removeEventListener('change', this.mobileSharePositionHandler);
          } else if (this.mobileViewportMql.removeListener) {
            this.mobileViewportMql.removeListener(this.mobileSharePositionHandler);
          }
        }
        if (this.elements.viewer) {
          this.elements.viewer.removeEventListener('slideChanged', this.galleryCounterSlideHandler);
        }
        if (this.galleryCounterResizeObserver) {
          this.galleryCounterResizeObserver.disconnect();
        }
        window.removeEventListener('load', this.galleryCounterPositionHandler);
        window.removeEventListener('resize', this.galleryCounterPositionHandler);
        window.removeEventListener('orientationchange', this.galleryCounterPositionHandler);
        this.unbindMobileSwipeHandlers();
      }

      onSlideChanged(event) {
        const thumbnail = this.elements.thumbnails.querySelector(
          `[data-target="${event.detail.currentElement.dataset.mediaId}"]`
        );
        this.setActiveThumbnail(thumbnail);
        this.syncGalleryCounter(event.detail.currentElement.dataset.mediaId);
        this.syncGalleryCounterPosition();
        this.syncMobileShareButtonPosition();
      }

      handleMobileShareClick(event) {
        const clickedButton = event?.currentTarget || null;
        const shareUrl = window.location.href;

        if (navigator.share) {
          navigator.share({ url: shareUrl, title: document.title }).catch(() => {});
          return;
        }

        if (navigator.clipboard && window.isSecureContext) {
          navigator.clipboard
            .writeText(shareUrl)
            .then(() => {
              if (!clickedButton) return;
              clickedButton.classList.add('is-copied');
              window.setTimeout(() => {
                clickedButton.classList.remove('is-copied');
              }, 1400);
            })
            .catch(() => {});
        }
      }

      setActiveMedia(mediaId, options = {}) {
        const { preventScroll = false } = options;
        const isDesktopViewport = this.mql.matches;
        const viewerSlider = this.elements.viewer?.slider || null;
        const activeMedia =
          this.elements.viewer.querySelector(`[data-media-id="${mediaId}"]`) ||
          this.elements.viewer.querySelector('[data-media-id]');
        if (!activeMedia) {
          return;
        }
        this.elements.viewer.querySelectorAll('[data-media-id]').forEach((element) => {
          element.classList.remove('is-active');
        });
        activeMedia?.classList?.add('is-active');
        this.syncGalleryCounter(mediaId);
        this.syncGalleryCounterPosition();
        this.syncMobileShareButtonPosition();

        this.preventStickyHeader();
        window.setTimeout(() => {
          const sliderToScroll = viewerSlider || activeMedia.parentElement;
          if (sliderToScroll) sliderToScroll.scrollTo({ left: activeMedia.offsetLeft });
          if (preventScroll || !isDesktopViewport) return;
          const activeMediaRect = activeMedia.getBoundingClientRect();
          // Don't scroll if the image is already in view
          if (activeMediaRect.top > -0.5) return;
          const top = activeMediaRect.top + window.scrollY;
          window.scrollTo({ top: top, behavior: 'smooth' });
          this.syncGalleryCounterPosition();
        });
        this.playActiveMedia(activeMedia);

        if (!this.elements.thumbnails) return;
        const activeThumbnail = this.elements.thumbnails.querySelector(`[data-target="${mediaId}"]`);
        this.setActiveThumbnail(activeThumbnail);
        this.announceLiveRegion(activeMedia, activeThumbnail.dataset.mediaPosition);
      }

      syncMobileShareButtonPosition() {
        const { mobileShareButtons, viewer } = this.elements;
        if (!mobileShareButtons.length || !viewer) return;

        const resetButtonPosition = (button) => {
          button.style.removeProperty('top');
          button.style.removeProperty('right');
          button.style.removeProperty('left');
          button.style.removeProperty('bottom');
        };

        if (!this.mobileViewportMql.matches) {
          mobileShareButtons.forEach(resetButtonPosition);
          return;
        }

        // Keep mobile share buttons aligned by CSS so the first slide matches subsequent slides.
        mobileShareButtons.forEach(resetButtonPosition);
      }

      getMobileCornerInsetPx() {
        const mediaProgress = this.querySelector('[data-gallery-stepper]');
        if (mediaProgress) {
          const progressStyles = window.getComputedStyle(mediaProgress);
          const progressRight = Number.parseFloat(progressStyles.right);
          if (!Number.isNaN(progressRight) && progressRight > 0) return progressRight;
        }

        const rootFontSize = Number.parseFloat(window.getComputedStyle(document.documentElement).fontSize) || 16;
        return rootFontSize * 0.65;
      }

      bindMobileSwipeHandlers() {
        if (!this.elements.viewer || !this.elements.viewer.slider || this.mobileSwipeHandlersBound) return;
        this.elements.viewer.slider.addEventListener('touchstart', this.mobileSwipeStartHandler, { passive: true });
        this.elements.viewer.slider.addEventListener('touchmove', this.mobileSwipeMoveHandler, { passive: false });
        this.elements.viewer.slider.addEventListener('touchend', this.mobileSwipeEndHandler);
        this.elements.viewer.slider.addEventListener('touchcancel', this.mobileSwipeCancelHandler);
        this.mobileSwipeHandlersBound = true;
      }

      unbindMobileSwipeHandlers() {
        if (!this.elements.viewer || !this.elements.viewer.slider || !this.mobileSwipeHandlersBound) return;
        this.elements.viewer.slider.removeEventListener('touchstart', this.mobileSwipeStartHandler);
        this.elements.viewer.slider.removeEventListener('touchmove', this.mobileSwipeMoveHandler);
        this.elements.viewer.slider.removeEventListener('touchend', this.mobileSwipeEndHandler);
        this.elements.viewer.slider.removeEventListener('touchcancel', this.mobileSwipeCancelHandler);
        this.mobileSwipeHandlersBound = false;
        this.mobileSwipeState = null;
      }

      handleMobileSwipeStart(event) {
        if (!this.mobileViewportMql.matches || !event.touches || event.touches.length !== 1) {
          this.mobileSwipeState = null;
          return;
        }
        const touch = event.touches[0];
        this.mobileSwipeState = {
          startX: touch.clientX,
          startY: touch.clientY,
          lastX: touch.clientX,
          lastY: touch.clientY,
          horizontalIntent: false,
        };
      }

      handleMobileSwipeMove(event) {
        if (!this.mobileViewportMql.matches || !this.mobileSwipeState || !event.touches || !event.touches.length) return;
        const touch = event.touches[0];
        this.mobileSwipeState.lastX = touch.clientX;
        this.mobileSwipeState.lastY = touch.clientY;
        const deltaX = touch.clientX - this.mobileSwipeState.startX;
        const deltaY = touch.clientY - this.mobileSwipeState.startY;

        if (
          !this.mobileSwipeState.horizontalIntent &&
          Math.abs(deltaX) > 8 &&
          Math.abs(deltaX) > Math.abs(deltaY)
        ) {
          this.mobileSwipeState.horizontalIntent = true;
        }

        if (this.mobileSwipeState.horizontalIntent) {
          event.preventDefault();
        }
      }

      handleMobileSwipeEnd(event) {
        if (!this.mobileViewportMql.matches || !this.mobileSwipeState) {
          this.mobileSwipeState = null;
          return;
        }
        const touch = event.changedTouches && event.changedTouches.length ? event.changedTouches[0] : null;
        const endX = touch ? touch.clientX : this.mobileSwipeState.lastX;
        const endY = touch ? touch.clientY : this.mobileSwipeState.lastY;
        const deltaX = endX - this.mobileSwipeState.startX;
        const deltaY = endY - this.mobileSwipeState.startY;
        const sliderWidth =
          (this.elements.viewer && this.elements.viewer.slider && this.elements.viewer.slider.clientWidth) ||
          window.innerWidth ||
          0;
        const swipeThreshold = Math.max(28, Math.round(sliderWidth * 0.08));
        const isHorizontalSwipe = Math.abs(deltaX) >= swipeThreshold && Math.abs(deltaX) > Math.abs(deltaY);

        if (isHorizontalSwipe) {
          this.cycleActiveMedia(deltaX < 0 ? 1 : -1);
        }

        this.mobileSwipeState = null;
      }

      handleMobileSwipeCancel() {
        this.mobileSwipeState = null;
      }

      getViewerMediaItems() {
        if (!this.elements.viewer || !this.elements.viewer.slider) return [];
        return Array.from(this.elements.viewer.slider.querySelectorAll(':scope > [data-media-id]'));
      }

      getActiveMediaIndex(mediaItems) {
        const activeIndex = mediaItems.findIndex((item) => item.classList.contains('is-active'));
        if (activeIndex >= 0) return activeIndex;

        if (!this.elements.viewer || !this.elements.viewer.slider) return 0;
        const currentScrollLeft = this.elements.viewer.slider.scrollLeft;
        let closestIndex = 0;
        let closestDistance = Number.POSITIVE_INFINITY;

        mediaItems.forEach((item, index) => {
          const distance = Math.abs(item.offsetLeft - currentScrollLeft);
          if (distance < closestDistance) {
            closestDistance = distance;
            closestIndex = index;
          }
        });

        return closestIndex;
      }

      cycleActiveMedia(step = 1) {
        const mediaItems = this.getViewerMediaItems();
        if (mediaItems.length < 2 || !Number.isFinite(step) || step === 0) return;

        const activeIndex = this.getActiveMediaIndex(mediaItems);
        const direction = step > 0 ? 1 : -1;
        const targetIndex = (activeIndex + direction + mediaItems.length) % mediaItems.length;
        const targetMediaId = mediaItems[targetIndex].dataset.mediaId;
        if (!targetMediaId) return;

        this.setActiveMedia(targetMediaId, { preventScroll: true });
        if (this.elements.viewer && typeof this.elements.viewer.updateGalleryArrows === 'function') {
          this.elements.viewer.updateGalleryArrows(targetIndex, mediaItems.length);
        }
      }

      syncGalleryCounter(mediaId) {
        const mediaProgress = this.querySelector('[data-gallery-stepper]');
        if (!mediaProgress || !this.elements.viewer) return;

        const mediaItems = this.elements.viewer.slider
          ? Array.from(this.elements.viewer.slider.querySelectorAll(':scope > [data-media-id]'))
          : Array.from(this.elements.viewer.querySelectorAll('.product__media-list > [data-media-id]'));
        if (!mediaItems.length) return;

        let activeIndex = mediaItems.findIndex((item) => item.dataset.mediaId === mediaId);
        if (activeIndex < 0) {
          activeIndex = mediaItems.findIndex((item) => item.classList.contains('is-active'));
        }
        const current = activeIndex >= 0 ? activeIndex + 1 : 1;
        const total = mediaItems.length;
        const progress = Math.min(100, Math.max(0, (current / total) * 100));

        const currentElement = mediaProgress.querySelector('.product-media-progress__current');
        const totalElement = mediaProgress.querySelector('.product-media-progress__total');
        if (currentElement) currentElement.textContent = current;
        if (totalElement) totalElement.textContent = total;
        mediaProgress.style.setProperty('--media-progress', `${progress}%`);
      }

      syncGalleryCounterPosition() {
        const mediaProgress = this.querySelector('[data-gallery-stepper]');
        if (!mediaProgress || !this.elements.viewer) return;

        if (this.mobileViewportMql.matches) {
          const inset = this.getMobileCornerInsetPx();
          const roundedInset = Math.round(inset);
          mediaProgress.style.setProperty('right', `${roundedInset}px`, 'important');
          mediaProgress.style.setProperty('bottom', `${roundedInset}px`, 'important');
          mediaProgress.style.setProperty('left', 'auto', 'important');
          mediaProgress.style.setProperty('top', 'auto', 'important');
          mediaProgress.style.setProperty('max-width', `calc(100% - ${roundedInset * 2}px)`, 'important');
          return;
        }

        const viewerRect = this.elements.viewer.getBoundingClientRect();
        const activeMediaItem =
          this.elements.viewer.querySelector('.product__media-list > .product__media-item.is-active') ||
          this.elements.viewer.querySelector('.product__media-list > .product__media-item');
        if (!activeMediaItem) return;

        const mediaFrame =
          activeMediaItem.querySelector('.product-media-container .product__media') ||
          activeMediaItem.querySelector('.product__media') ||
          activeMediaItem;
        const frameRect = mediaFrame.getBoundingClientRect();

        const inset = 10;
        const right = Math.max(0, viewerRect.right - frameRect.right) + inset;
        const bottom = Math.max(0, viewerRect.bottom - frameRect.bottom) + inset;

        mediaProgress.style.setProperty('right', `${Math.round(right)}px`, 'important');
        mediaProgress.style.setProperty('bottom', `${Math.round(bottom)}px`, 'important');
        mediaProgress.style.setProperty('left', 'auto', 'important');
        mediaProgress.style.setProperty('top', 'auto', 'important');
        mediaProgress.style.setProperty('max-width', `calc(100% - ${Math.round(right) + inset}px)`, 'important');
      }

      setActiveThumbnail(thumbnail) {
        if (!this.elements.thumbnails || !thumbnail) return;

        this.elements.thumbnails
          .querySelectorAll('button')
          .forEach((element) => element.removeAttribute('aria-current'));
        thumbnail.querySelector('button').setAttribute('aria-current', true);
        if (this.elements.thumbnails.isSlideVisible(thumbnail, 10)) return;

        this.elements.thumbnails.slider.scrollTo({ left: thumbnail.offsetLeft });
      }

      announceLiveRegion(activeItem, position) {
        const image = activeItem.querySelector('.product__modal-opener--image img');
        if (!image) return;
        image.onload = () => {
          this.elements.liveRegion.setAttribute('aria-hidden', false);
          this.elements.liveRegion.innerHTML = window.accessibilityStrings.imageAvailable.replace('[index]', position);
          setTimeout(() => {
            this.elements.liveRegion.setAttribute('aria-hidden', true);
          }, 2000);
        };
        image.src = image.src;
      }

      playActiveMedia(activeItem) {
        window.pauseAllMedia();
        const deferredMedia = activeItem.querySelector('.deferred-media');
        if (deferredMedia) deferredMedia.loadContent(false);
      }

      preventStickyHeader() {
        this.stickyHeader = this.stickyHeader || document.querySelector('sticky-header');
        if (!this.stickyHeader) return;
        this.stickyHeader.dispatchEvent(new Event('preventHeaderReveal'));
      }

      removeListSemantic() {
        if (!this.elements.viewer.slider) return;
        this.elements.viewer.slider.setAttribute('role', 'presentation');
        this.elements.viewer.sliderItems.forEach((slide) => slide.setAttribute('role', 'presentation'));
      }
    }
  );
}

if (!customElements.get('price-per-item')) {
  customElements.define(
    'price-per-item',
    class PricePerItem extends HTMLElement {
      constructor() {
        super();
        this.variantId = this.dataset.variantId;
        this.input = document.getElementById(`Quantity-${this.dataset.sectionId || this.dataset.variantId}`);
        if (this.input) {
          this.input.addEventListener('change', this.onInputChange.bind(this));
        }

        this.getVolumePricingArray();
      }

      updatePricePerItemUnsubscriber = undefined;
      variantIdChangedUnsubscriber = undefined;

      connectedCallback() {
        // Update variantId if variant is switched on product page
        this.variantIdChangedUnsubscriber = subscribe(PUB_SUB_EVENTS.variantChange, (event) => {
          this.variantId = event.data.variant.id.toString();
          this.getVolumePricingArray();
        });

        this.updatePricePerItemUnsubscriber = subscribe(PUB_SUB_EVENTS.cartUpdate, (response) => {
          if (!response.cartData) return;

          // Item was added to cart via product page
          if (response.cartData['variant_id'] !== undefined) {
            if (response.productVariantId === this.variantId) this.updatePricePerItem(response.cartData.quantity);
            // Qty was updated in cart
          } else if (response.cartData.item_count !== 0) {
            const isVariant = response.cartData.items.find((item) => item.variant_id.toString() === this.variantId);
            if (isVariant && isVariant.id.toString() === this.variantId) {
              // The variant is still in cart
              this.updatePricePerItem(isVariant.quantity);
            } else {
              // The variant was removed from cart, qty is 0
              this.updatePricePerItem(0);
            }
            // All items were removed from cart
          } else {
            this.updatePricePerItem(0);
          }
        });
      }

      disconnectedCallback() {
        if (this.updatePricePerItemUnsubscriber) {
          this.updatePricePerItemUnsubscriber();
        }
        if (this.variantIdChangedUnsubscriber) {
          this.variantIdChangedUnsubscriber();
        }
      }

      onInputChange() {
        this.updatePricePerItem();
      }

      updatePricePerItem(updatedCartQuantity) {
        if (this.input) {
          this.enteredQty = parseInt(this.input.value);
          this.step = parseInt(this.input.step)
        }

        // updatedCartQuantity is undefined when qty is updated on product page. We need to sum entered qty and current qty in cart.
        // updatedCartQuantity is not undefined when qty is updated in cart. We need to sum qty in cart and min qty for product.
        this.currentQtyForVolumePricing = updatedCartQuantity === undefined ? this.getCartQuantity(updatedCartQuantity) + this.enteredQty : this.getCartQuantity(updatedCartQuantity) + parseInt(this.step);

        if (this.classList.contains('variant-item__price-per-item')) {
          this.currentQtyForVolumePricing = this.getCartQuantity(updatedCartQuantity);
        }
        for (let pair of this.qtyPricePairs) {
          if (this.currentQtyForVolumePricing >= pair[0]) {
            const pricePerItemCurrent = document.querySelector(`price-per-item[id^="Price-Per-Item-${this.dataset.sectionId || this.dataset.variantId}"] .price-per-item span`);
            this.classList.contains('variant-item__price-per-item') ? pricePerItemCurrent.innerHTML = window.quickOrderListStrings.each.replace('[money]', pair[1]) : pricePerItemCurrent.innerHTML = pair[1];
            break;
          }
        }
      }

      getCartQuantity(updatedCartQuantity) {
        return (updatedCartQuantity || updatedCartQuantity === 0) ? updatedCartQuantity : parseInt(this.input.dataset.cartQuantity);
      }

      getVolumePricingArray() {
        const volumePricing = document.getElementById(`Volume-${this.dataset.sectionId || this.dataset.variantId}`);
        this.qtyPricePairs = [];

        if (volumePricing) {
          volumePricing.querySelectorAll('li').forEach(li => {
            const qty = parseInt(li.querySelector('span:first-child').textContent);
            const price = (li.querySelector('span:not(:first-child):last-child').dataset.text);
            this.qtyPricePairs.push([qty, price]);
          });
        }
        this.qtyPricePairs.reverse();
      }
    }
  );
}

(function () {
  const initProductDescriptions = function () {
  const descriptions = document.querySelectorAll("[data-product-description]");

  if (!descriptions.length) return;

  const getLocaleCopy = function () {
    const copyMap = window.DLM_PRODUCT_PAGE_COPY;
    if (!copyMap || typeof copyMap !== "object") return {};

    const localeSource =
      (window.Shopify && typeof window.Shopify.locale === "string" && window.Shopify.locale) ||
      (document.documentElement && document.documentElement.lang) ||
      "";
    const locale = String(localeSource || "").replace("_", "-").toLowerCase();
    const root = locale.split("-")[0];
    const candidates = [locale];

    if (root && root !== locale) candidates.push(root);
    if (root === "pt") candidates.push("pt-BR", "pt-PT");
    if (root === "ro") candidates.push("ro", "ro-RO");
    if (root === "no") candidates.push("no", "nb");
    candidates.push("en");

    const keys = Object.keys(copyMap);
    for (let index = 0; index < candidates.length; index += 1) {
      const candidate = candidates[index];
      const key = keys.find(function (mapKey) {
        return mapKey.toLowerCase() === candidate.toLowerCase();
      });
      if (key && copyMap[key]) return copyMap[key];
    }

    return {};
  };

  const localeCopy = getLocaleCopy();
  const copy = {
    detailsEyebrow: localeCopy.description_details_eyebrow || "Details",
    highlightsHeading: localeCopy.description_highlights_heading || "Why You'll Love It",
    sizeChartHeading: localeCopy.description_size_chart_heading || "Size Chart",
    productDetailsHeading: localeCopy.description_product_details_heading || "Product Details",
    sizeChartMeta: localeCopy.description_size_chart_meta || "Measurements from the supplier source table",
    productDetailsMeta: localeCopy.description_product_details_meta || "Structured product information",
  };

  const getTextContent = function (element) {
    return String(element && element.textContent ? element.textContent : "")
      .replace(/\s+/g, " ")
      .trim();
  };

  const isEmptyList = function (element) {
    if (!element || !/^(UL|OL)$/.test(element.tagName)) return false;

    return !Array.from(element.children).some(function (child) {
      return child.tagName === "LI" && getTextContent(child) !== "";
    });
  };

  const isTextBlock = function (element) {
    if (!element || !/^(P|DIV)$/.test(element.tagName)) return false;
    if (element.querySelector("table, ul, ol, img, iframe, video, blockquote")) return false;

    return getTextContent(element) !== "";
  };

  const shouldPromoteToFeature = function (element) {
    const text = getTextContent(element);

    if (!text) return false;
    if (text.length > 220) return false;

    return (text.match(/[.!?]/g) || []).length <= 2;
  };

  const hasOnlySafeWrapperAttributes = function (element) {
    return Array.from(element.attributes || []).every(function (attribute) {
      if (/^(data-|aria-)/.test(attribute.name)) return true;
      if (attribute.name !== "style") return false;

      return /^text-align:\s*(start|left);?$/i.test(String(attribute.value || "").trim());
    });
  };

  const isTransparentDescriptionWrapper = function (element) {
    if (!element || element.tagName !== "DIV") return false;
    if (!element.children.length) return false;
    if (!hasOnlySafeWrapperAttributes(element)) return false;

    return Array.from(element.children).every(function (child) {
      return /^(P|DIV|UL|OL|TABLE|IMG|FIGURE|BR)$/.test(child.tagName);
    });
  };

  const isEmptySpacerBlock = function (element) {
    if (!element) return false;
    if (element.tagName === "BR") return true;
    if (!/^(P|DIV)$/.test(element.tagName)) return false;
    if (element.querySelector("table, ul, ol, img, iframe, video, figure, blockquote")) return false;

    return getTextContent(element) === "";
  };

  const isListItemBlockElement = function (element) {
    if (!element || element.nodeType !== 1) return false;

    return /^(P|DIV|UL|OL|TABLE|FIGURE|IMG|VIDEO|IFRAME|BLOCKQUOTE|H1|H2|H3|H4|H5|H6)$/.test(element.tagName);
  };

  const wrapInlineListItemContent = function (item) {
    if (!item || item.tagName !== "LI") return;

    let inlineNodes = [];

    const flushInlineNodes = function (anchorNode) {
      if (!inlineNodes.length) return;

      const paragraph = document.createElement("p");
      paragraph.className = "product-copy__item-copy";

      inlineNodes.forEach(function (node) {
        paragraph.appendChild(node);
      });

      item.insertBefore(paragraph, anchorNode || null);
      inlineNodes = [];
    };

    Array.from(item.childNodes).forEach(function (node) {
      if (node.nodeType === 3) {
        if (String(node.textContent || "").trim() === "") {
          node.remove();
          return;
        }

        inlineNodes.push(node);
        return;
      }

      if (node.nodeType !== 1) {
        node.remove();
        return;
      }

      if (isListItemBlockElement(node)) {
        flushInlineNodes(node);
        return;
      }

      inlineNodes.push(node);
    });

    flushInlineNodes(null);
  };

  const normalizeDescriptionStructure = function (container) {
    let changed = true;

    while (changed) {
      changed = false;

      Array.from(container.children).forEach(function (child) {
        if (!isTransparentDescriptionWrapper(child)) return;

        while (child.firstChild) {
          container.insertBefore(child.firstChild, child);
        }

        child.remove();
        changed = true;
      });

      Array.from(container.children).forEach(function (child) {
        if (!isEmptyList(child) && !isEmptySpacerBlock(child)) return;
        child.remove();
        changed = true;
      });
    }
  };

  const cleanListItem = function (item) {
    if (!item || item.tagName !== "LI") return;

    Array.from(item.children).forEach(function (child) {
      if (/^(P|DIV|SPAN)$/.test(child.tagName) && getTextContent(child) === "") {
        child.remove();
      }
    });

    const paragraphs = Array.from(item.children).filter(function (child) {
      return child.tagName === "P" && getTextContent(child) !== "";
    });
    const hasOnlyParagraphs = paragraphs.length > 1 && paragraphs.length === item.children.length;

    if (hasOnlyParagraphs) {
      const firstParagraph = paragraphs[0];

      paragraphs.slice(1).forEach(function (paragraph) {
        if (getTextContent(firstParagraph) !== "" && getTextContent(paragraph) !== "") {
          firstParagraph.appendChild(document.createTextNode(" "));
        }

        while (paragraph.firstChild) {
          firstParagraph.appendChild(paragraph.firstChild);
        }

        paragraph.remove();
      });
    }

    wrapInlineListItemContent(item);
  };

  const normalizeList = function (listElement, className) {
    Array.from(listElement.children).forEach(function (child) {
      if (child.tagName === "LI") return;

      const item = document.createElement("li");

      while (child.firstChild) {
        item.appendChild(child.firstChild);
      }

      child.replaceWith(item);
    });

    Array.from(listElement.children).forEach(function (item) {
      cleanListItem(item);
      if (item.tagName !== "LI" || getTextContent(item) !== "") return;
      item.remove();
    });

    String(className || "")
      .split(/\s+/)
      .filter(Boolean)
      .forEach(function (token) {
        listElement.classList.add(token);
      });
  };

  const shouldSuppressVisibleSizeChart = function (tableElement) {
    if (!tableElement) return false;

    const firstHeader = tableElement.querySelector("th");
    const headerText = firstHeader ? getTextContent(firstHeader).toLowerCase() : "";
    const tableId = String(tableElement.id || "").toLowerCase();
    const isSizeChart = tableId.indexOf("size-chart") !== -1 || headerText === "size";
    if (!isSizeChart) return false;

    const productRoot = tableElement.closest("[id^='MainProduct-']");
    return !!(productRoot && productRoot.querySelector("[data-matching-size-guide]"));
  };

  const wrapTable = function (tableElement) {
    if (!tableElement || tableElement.closest(".product-copy__table-card")) return;

    if (shouldSuppressVisibleSizeChart(tableElement)) {
      tableElement.hidden = true;
      tableElement.setAttribute("aria-hidden", "true");
      tableElement.setAttribute("data-size-chart-source-only", "true");
      tableElement.style.setProperty("display", "none", "important");
      return;
    }

    const tableCard = document.createElement("div");
    const tableHeader = document.createElement("div");
    const tableTitle = document.createElement("h3");
    const tableMeta = document.createElement("p");
    const tableScroll = document.createElement("div");
    const firstHeader = tableElement.querySelector("th");
    const headerText = firstHeader ? getTextContent(firstHeader).toLowerCase() : "";
    const tableId = String(tableElement.id || "").toLowerCase();

    tableCard.className = "product-copy__table-card";
    if (tableId.indexOf("size-chart") !== -1 || headerText === "size") {
      tableCard.classList.add("product-copy__table-card--size-chart");
    }

    tableHeader.className = "product-copy__table-header";
    tableTitle.className = "product-copy__section-title";
    tableTitle.textContent = tableCard.classList.contains("product-copy__table-card--size-chart")
      ? copy.sizeChartHeading
      : copy.productDetailsHeading;
    tableMeta.className = "product-copy__section-meta";
    tableMeta.textContent = tableCard.classList.contains("product-copy__table-card--size-chart")
      ? copy.sizeChartMeta
      : copy.productDetailsMeta;

    tableScroll.className = "product-copy__table-scroll";
    tableElement.classList.add("product-copy__table");

    tableElement.parentNode.insertBefore(tableCard, tableElement);
    tableCard.appendChild(tableHeader);
    tableHeader.appendChild(tableTitle);
    tableHeader.appendChild(tableMeta);
    tableCard.appendChild(tableScroll);
    tableScroll.appendChild(tableElement);
  };

  const ensureSectionHeading = function (element, title, variantClass) {
    if (!element) return;
    if (element.previousElementSibling && element.previousElementSibling.classList.contains("product-copy__section-heading")) {
      return;
    }

    const heading = document.createElement("div");
    const eyebrow = document.createElement("span");
    const headingTitle = document.createElement("h3");

    heading.className = "product-copy__section-heading";
    if (variantClass) heading.classList.add(variantClass);

    eyebrow.className = "product-copy__section-eyebrow";
    eyebrow.textContent = copy.detailsEyebrow;

    headingTitle.className = "product-copy__section-title";
    headingTitle.textContent = title;

    heading.appendChild(eyebrow);
    heading.appendChild(headingTitle);
    element.parentNode.insertBefore(heading, element);
  };

  descriptions.forEach(function (description) {
    if (description.dataset.productDescriptionReady === "true") return;

    normalizeDescriptionStructure(description);

    let leadAssigned = false;
    let highlightsAssigned = false;
    let pendingFeatureParagraphs = [];

    const flushPendingFeatureParagraphs = function () {
      if (!pendingFeatureParagraphs.length) return;

      if (!highlightsAssigned && pendingFeatureParagraphs.length >= 2) {
        const list = document.createElement("ul");
        const firstParagraph = pendingFeatureParagraphs[0];

        list.className = "product-copy__highlights product-copy__feature-list";
        firstParagraph.parentNode.insertBefore(list, firstParagraph);

        pendingFeatureParagraphs.forEach(function (paragraph) {
          const item = document.createElement("li");

          while (paragraph.firstChild) {
            item.appendChild(paragraph.firstChild);
          }

          list.appendChild(item);
          paragraph.remove();
        });

        ensureSectionHeading(list, copy.highlightsHeading, "product-copy__section-heading--features");
        highlightsAssigned = true;
      } else {
        pendingFeatureParagraphs.forEach(function (paragraph) {
          paragraph.classList.add("product-copy__body");
        });
      }

      pendingFeatureParagraphs = [];
    };

    const mergePendingFeatureParagraphsIntoList = function (listElement) {
      if (!pendingFeatureParagraphs.length) return;

      const fragment = document.createDocumentFragment();

      pendingFeatureParagraphs.forEach(function (paragraph) {
        const item = document.createElement("li");

        while (paragraph.firstChild) {
          item.appendChild(paragraph.firstChild);
        }

        fragment.appendChild(item);
        paragraph.remove();
      });

      listElement.insertBefore(fragment, listElement.firstChild);
      pendingFeatureParagraphs = [];
    };

    Array.from(description.children).forEach(function (child) {
      if (isEmptyList(child) || isEmptySpacerBlock(child)) {
        child.remove();
        return;
      }

      if (child.tagName === "TABLE") {
        flushPendingFeatureParagraphs();
        wrapTable(child);
        return;
      }

      if (/^(UL|OL)$/.test(child.tagName)) {
        mergePendingFeatureParagraphsIntoList(child);
        normalizeList(
          child,
          highlightsAssigned ? "product-copy__body-list" : "product-copy__highlights product-copy__feature-list"
        );
        if (!highlightsAssigned) {
          ensureSectionHeading(child, copy.highlightsHeading, "product-copy__section-heading--features");
        }
        highlightsAssigned = true;
        return;
      }

      if (isTextBlock(child)) {
        if (!leadAssigned) {
          child.classList.add("product-copy__lead");
          leadAssigned = true;
          return;
        }

        if (!highlightsAssigned && shouldPromoteToFeature(child)) {
          pendingFeatureParagraphs.push(child);
          return;
        }

        flushPendingFeatureParagraphs();
        child.classList.add("product-copy__body");
        return;
      }

      flushPendingFeatureParagraphs();

      if (/^(IMG|FIGURE)$/.test(child.tagName)) {
        child.classList.add("product-copy__media");
      }
    });

    flushPendingFeatureParagraphs();
    description.dataset.productDescriptionReady = "true";
  });
  };

  if (document.readyState === "loading" && !document.querySelector("[data-product-description]")) {
    document.addEventListener("DOMContentLoaded", initProductDescriptions, { once: true });
    return;
  }

  initProductDescriptions();
})();

if (!customElements.get('product-form')) {
  customElements.define(
    'product-form',
    class ProductForm extends HTMLElement {
      constructor() {
        super();

        this.form = this.querySelector('form');
        this.form.querySelector('[name=id]').disabled = false;
        this.form.addEventListener('submit', this.onSubmitHandler.bind(this));
        this.cart = document.querySelector('cart-notification') || document.querySelector('cart-drawer');
        this.submitButton = this.querySelector('[type="submit"]');

        if (document.querySelector('cart-drawer')) this.submitButton.setAttribute('aria-haspopup', 'dialog');

        this.hideErrors = this.dataset.hideErrors === 'true';
      }

      onSubmitHandler(evt) {
        evt.preventDefault();
        if (this.submitButton.getAttribute('aria-disabled') === 'true') return;

        this.handleErrorMessage();

        this.submitButton.setAttribute('aria-disabled', true);
        this.submitButton.classList.add('loading');
        this.querySelector('.loading__spinner').classList.remove('hidden');

        const config = fetchConfig('javascript');
        config.headers['X-Requested-With'] = 'XMLHttpRequest';
        delete config.headers['Content-Type'];

        const formData = new FormData(this.form);
        if (this.cart) {
          formData.append(
            'sections',
            this.cart.getSectionsToRender().map((section) => section.id)
          );
          formData.append('sections_url', window.location.pathname);
          this.cart.setActiveElement(document.activeElement);
        }
        config.body = formData;

        fetch(`${routes.cart_add_url}`, config)
          .then((response) => response.json())
          .then((response) => {
            if (response.status) {
              publish(PUB_SUB_EVENTS.cartError, {
                source: 'product-form',
                productVariantId: formData.get('id'),
                errors: response.errors || response.description,
                message: response.message,
              });
              this.handleErrorMessage(response.description);

              const soldOutMessage = this.submitButton.querySelector('.sold-out-message');
              if (!soldOutMessage) return;
              this.submitButton.setAttribute('aria-disabled', true);
              this.submitButton.querySelector('span').classList.add('hidden');
              soldOutMessage.classList.remove('hidden');
              this.error = true;
              return;
            } else if (!this.cart) {
              window.location = window.routes.cart_url;
              return;
            }

            if (!this.error)
              publish(PUB_SUB_EVENTS.cartUpdate, {
                source: 'product-form',
                productVariantId: formData.get('id'),
                cartData: response,
              });
            this.error = false;
            const quickAddModal = this.closest('quick-add-modal');
            if (quickAddModal) {
              document.body.addEventListener(
                'modalClosed',
                () => {
                  setTimeout(() => {
                    this.cart.renderContents(response);
                  });
                },
                { once: true }
              );
              quickAddModal.hide(true);
            } else {
              this.cart.renderContents(response);
            }
          })
          .catch((e) => {
            console.error(e);
          })
          .finally(() => {
            this.submitButton.classList.remove('loading');
            if (this.cart && this.cart.classList.contains('is-empty')) this.cart.classList.remove('is-empty');
            if (!this.error) this.submitButton.removeAttribute('aria-disabled');
            this.querySelector('.loading__spinner').classList.add('hidden');
          });
      }

      handleErrorMessage(errorMessage = false) {
        if (this.hideErrors) return;

        this.errorMessageWrapper =
          this.errorMessageWrapper || this.querySelector('.product-form__error-message-wrapper');
        if (!this.errorMessageWrapper) return;
        this.errorMessage = this.errorMessage || this.errorMessageWrapper.querySelector('.product-form__error-message');

        this.errorMessageWrapper.toggleAttribute('hidden', !errorMessage);

        if (errorMessage) {
          this.errorMessage.textContent = errorMessage;
        }
      }
    }
  );
}

if (!customElements.get('product-info')) {
  customElements.define(
    'product-info',
    class ProductInfo extends HTMLElement {
      constructor() {
        super();
        this.input = this.querySelector('.quantity__input');
        this.currentVariant = this.querySelector('.product-variant-id');
        this.submitButton = this.querySelector('[type="submit"]');
      }

      cartUpdateUnsubscriber = undefined;
      variantChangeUnsubscriber = undefined;

      connectedCallback() {
        if (!this.input) return;
        this.quantityForm = this.querySelector('.product-form__quantity');
        if (!this.quantityForm) return;
        this.setQuantityBoundries();
        if (!this.dataset.originalSection) {
          this.cartUpdateUnsubscriber = subscribe(PUB_SUB_EVENTS.cartUpdate, this.fetchQuantityRules.bind(this));
        }
        this.variantChangeUnsubscriber = subscribe(PUB_SUB_EVENTS.variantChange, (event) => {
          const sectionId = this.dataset.originalSection ? this.dataset.originalSection : this.dataset.section;
          if (event.data.sectionId !== sectionId) return;
          this.updateQuantityRules(event.data.sectionId, event.data.html);
          this.setQuantityBoundries();
        });
      }

      disconnectedCallback() {
        if (this.cartUpdateUnsubscriber) {
          this.cartUpdateUnsubscriber();
        }
        if (this.variantChangeUnsubscriber) {
          this.variantChangeUnsubscriber();
        }
      }

      setQuantityBoundries() {
        const data = {
          cartQuantity: this.input.dataset.cartQuantity ? parseInt(this.input.dataset.cartQuantity) : 0,
          min: this.input.dataset.min ? parseInt(this.input.dataset.min) : 1,
          max: this.input.dataset.max ? parseInt(this.input.dataset.max) : null,
          step: this.input.step ? parseInt(this.input.step) : 1,
        };

        let min = data.min;
        const max = data.max === null ? data.max : data.max - data.cartQuantity;
        if (max !== null) min = Math.min(min, max);
        if (data.cartQuantity >= data.min) min = Math.min(min, data.step);
        this.input.min = min;

        if (max) {
          this.input.max = max;
        } else {
          this.input.removeAttribute('max');
        }
        this.input.value = min;
        publish(PUB_SUB_EVENTS.quantityUpdate, undefined);
      }

      fetchQuantityRules() {
        if (!this.currentVariant || !this.currentVariant.value) return;
        this.querySelector('.quantity__rules-cart .loading__spinner').classList.remove('hidden');
        fetch(`${this.dataset.url}?variant=${this.currentVariant.value}&section_id=${this.dataset.section}`)
          .then((response) => {
            return response.text();
          })
          .then((responseText) => {
            const html = new DOMParser().parseFromString(responseText, 'text/html');
            this.updateQuantityRules(this.dataset.section, html);
            this.setQuantityBoundries();
          })
          .catch((e) => {
            console.error(e);
          })
          .finally(() => {
            this.querySelector('.quantity__rules-cart .loading__spinner').classList.add('hidden');
          });
      }

      updateQuantityRules(sectionId, html) {
        const quantityFormUpdated = html.getElementById(`Quantity-Form-${sectionId}`);
        const selectors = ['.quantity__input', '.quantity__rules', '.quantity__label'];
        for (let selector of selectors) {
          const current = this.quantityForm.querySelector(selector);
          const updated = quantityFormUpdated.querySelector(selector);
          if (!current || !updated) continue;
          if (selector === '.quantity__input') {
            const attributes = ['data-cart-quantity', 'data-min', 'data-max', 'step'];
            for (let attribute of attributes) {
              const valueUpdated = updated.getAttribute(attribute);
              if (valueUpdated !== null) {
                current.setAttribute(attribute, valueUpdated);
              } else {
                current.removeAttribute(attribute);
              }
            }
          } else {
            current.innerHTML = updated.innerHTML;
          }
        }
      }
    }
  );
}

if (!customElements.get('product-modal')) {
  customElements.define(
    'product-modal',
    class ProductModal extends ModalDialog {
      constructor() {
        super();
      }

      hide() {
        super.hide();
      }

      show(opener) {
        super.show(opener);
        this.showActiveMedia();
      }

      showActiveMedia() {
        this.querySelectorAll(
          `[data-media-id]:not([data-media-id="${this.openedBy.getAttribute('data-media-id')}"])`
        ).forEach((element) => {
          element.classList.remove('active');
        });
        const activeMedia = this.querySelector(`[data-media-id="${this.openedBy.getAttribute('data-media-id')}"]`);
        const activeMediaTemplate = activeMedia.querySelector('template');
        const activeMediaContent = activeMediaTemplate ? activeMediaTemplate.content : null;
        activeMedia.classList.add('active');
        activeMedia.scrollIntoView();

        const container = this.querySelector('[role="document"]');
        container.scrollLeft = (activeMedia.width - container.clientWidth) / 2;

        if (
          activeMedia.nodeName == 'DEFERRED-MEDIA' &&
          activeMediaContent &&
          activeMediaContent.querySelector('.js-youtube')
        )
          activeMedia.loadContent();
      }
    }
  );
}

