.template-product .page-width--product-main ul li a::after,
.template-product .page-width--product-main ul li .subcategory a::after {
  content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 2px;
  background-color: #FF6600; transform: scaleX(0); transform-origin: bottom right;
  transition: transform 0.3s ease-out;
}

.template-product .page-width--product-main ul li a:hover::after,
.template-product .page-width--product-main ul li .subcategory a:hover::after,
.template-product .page-width--product-main ul li a.active::after,
